$page_title='Inteligencia de Amenazas';require_once __DIR__.'/../../includes/load.php';require_once __DIR__.'/../../config/app.php';require_once __DIR__.'/funciones.php';ma_schema();require_permiso('monitor_amenazas','ver');
$period=trim((string)($_GET['periodo']??$_POST['periodo']??date('Y-m')));if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$period))$period=date('Y-m');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_validate_or_fail();require_permiso('monitor_amenazas','editar');$action=$_POST['action']??'';
 if($action==='sync'){try{$s=ma_sync_all();$session->msg('s',"Sincronizacion: {$s['new']} nuevas y {$s['updated']} actualizadas.");}catch(Throwable $e){$session->msg('d','No se pudo sincronizar: '.$e->getMessage());}redirect('index.php?periodo='.urlencode($period),false);}
 if($action==='quick_evaluate'){$id=(int)($_POST['IdAmenaza']??0);$aplica=strtoupper(trim((string)($_POST['Aplica']??'')));$analisis=trim((string)($_POST['Analisis']??''));$accion=trim((string)($_POST['Accion']??''));$prioridad=strtoupper(trim((string)($_POST['Prioridad']??'CRITICA')));
  if($id<=0||!in_array($aplica,['SI','NO','POR CONFIRMAR'],true)||$analisis==='')$session->msg('d','Indique si aplica y escriba que verifico.');
  elseif($aplica==='SI'&&$accion==='')$session->msg('d','Si aplica, indique como actuo o que accion realizara.');
  else{if(!in_array($prioridad,['CRITICA','ALTA','MEDIA','BAJA'],true))$prioridad='CRITICA';$estado=$aplica==='NO'?'CERRADA':($accion!==''?'EN TRATAMIENTO':'EN ANALISIS');$db->query("INSERT INTO ti_amenazas_evaluaciones(IdAmenaza,Aplica,Prioridad,Estado,Analisis,Accion,Responsable,EvaluadoPor) VALUES($id,".ma_q($aplica).','.ma_q($prioridad).','.ma_q($estado).','.ma_q($analisis).','.ma_q($accion).','.ma_q(ma_user_name()).','.ma_user_id().')');$session->msg('s','Evaluacion registrada en el historial.');}redirect('index.php?periodo='.urlencode($period),false);}}
$periods=find_by_sql("SELECT DISTINCT DATE_FORMAT(FechaPublicacion,'%Y-%m') Periodo FROM ti_amenazas WHERE FechaPublicacion IS NOT NULL ORDER BY Periodo DESC");$start=$period.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));
$latest="SELECT e.* FROM ti_amenazas_evaluaciones e INNER JOIN(SELECT IdAmenaza,MAX(IdEvaluacion) IdEvaluacion FROM ti_amenazas_evaluaciones GROUP BY IdAmenaza)x ON x.IdEvaluacion=e.IdEvaluacion";
$rows=find_by_sql("SELECT a.*,e.Aplica,e.Estado EstadoEval,e.Prioridad,e.Analisis,e.Accion FROM ti_amenazas a LEFT JOIN ($latest)e ON e.IdAmenaza=a.IdAmenaza WHERE a.FechaPublicacion>=".ma_q($start)." AND a.FechaPublicacion<".ma_q($end)." AND(a.ExplotacionConocida=1 OR a.Severidad IN('CRITICA','ALTA','CRITICAL','HIGH')) ORDER BY a.ExplotacionConocida DESC,FIELD(a.Severidad,'CRITICA','CRITICAL','ALTA','HIGH','POR EVALUAR') ASC,a.FechaPublicacion DESC");
$historical=(int)($db->fetch_assoc($db->query('SELECT COUNT(*) Total FROM ti_amenazas'))['Total']??0);$total=count($rows);$pending=$applicable=$closed=0;foreach($rows as $r){if(!$r['EstadoEval'])$pending++;if($r['Aplica']==='SI')$applicable++;if($r['EstadoEval']==='CERRADA')$closed++;}
include_once __DIR__.'/../../layouts/header.php';?>
