<?php foreach($rows as $r):?><tr><td><span class="th-source"><?=ma_h($r['Fuente'])?></span><?php if($r['ExplotacionConocida']):?><div><span class="badge badge-danger">EXPLOTACIÓN CONOCIDA</span></div><?php endif;?><span class="badge badge-warning mt-1"><?=ma_h($r['Severidad'])?></span></td><td class="th-title"><strong><?=ma_h($r['Titulo'])?></strong><div class="small text-muted mt-1"><?=ma_h(mb_strimwidth($r['Descripcion'],0,240,'...'))?></div></td><td><strong><?=ma_h($r['Cve']?:'-')?></strong><div class="small"><?=ma_h(trim($r['Fabricante'].' '.$r['Producto']))?></div></td><td><?=ma_h($r['FechaPublicacion']?:'-')?></td><td class="th-review"><?php if(tiene_permiso('monitor_amenazas','editar')):?><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="quick_evaluate"><input type="hidden" name="periodo" value="<?=ma_h($period)?>"><input type="hidden" name="IdAmenaza" value="<?=(int)$r['IdAmenaza']?>"><div class="form-row"><div class="col-5"><select name="Aplica" class="form-control form-control-sm"><option value="POR CONFIRMAR" <?=$r['Aplica']==='POR CONFIRMAR'?'selected':''?>>Por confirmar</option><option value="SI" <?=$r['Aplica']==='SI'?'selected':''?>>Sí aplica</option><option value="NO" <?=$r['Aplica']==='NO'?'selected':''?>>No aplica</option></select></div><div class="col-4"><select name="Prioridad" class="form-control form-control-sm"><?php foreach(['CRITICA','ALTA','MEDIA','BAJA'] as $v):?><option <?=$r['Prioridad']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-3"><button class="btn btn-info btn-sm btn-block"><i class="fas fa-save"></i></button></div></div><textarea name="Analisis" class="form-control form-control-sm mt-1" required placeholder="¿Qué verificó para decidir si aplica?"><?=ma_h($r['Analisis']??'')?></textarea><textarea name="Accion" class="form-control form-control-sm mt-1" placeholder="¿Cómo actuó o qué realizará?"><?=ma_h($r['Accion']??'')?></textarea></form><?php else:?><strong><?=ma_h($r['Aplica']?:'PENDIENTE')?></strong><div><?=ma_h($r['Accion']?:'Sin actuación')?></div><?php endif;?></td><td><a class="btn btn-sm btn-outline-info" href="detalle.php?id=<?=(int)$r['IdAmenaza']?>" title="Historial y evidencia"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5">No hay amenazas críticas o altas para este periodo.</td></tr><?php endif;?></tbody></table></div></div>
